const DefaultAuthSessionCookieName = "sessiontoken"

type AuthConfig struct {
	// SessionTokenGenerator is optional; defaults to sesstokgen.Generator
	SessionTokenGenerator sessmanager.TokenGenerator

	// TokenCookie is optional; defaults to DefaultAuthSessionCookieName
	TokenCookie AuthSessionConfigTokenCookie

	// DisableHTTPOnly is optional; By default, httponly is enabled.
	DisableHTTPOnly bool
}

type AuthSessionConfigTokenCookie struct {
	// Name is optional; Default is DefaultAuthSessionCookieName
	Name string
	// Domain is optional; Not set by default.
	Domain string
}

// WithAuth sets session-based authentication configuration.
func WithAuth(o AuthConfig) ServerOption {
	return func(s *Server) error {
		if o.TokenCookie.Name == "" {
			o.TokenCookie.Name = DefaultAuthSessionCookieName
		}
		s.authConf = &o
		s.sessionTokenGenerator = o.SessionTokenGenerator
		return nil
	}
}

func (s *Server) setSessionCookie(w http.ResponseWriter, value string) {
	cookie := http.Cookie{
		Name:     s.authConf.TokenCookie.Name,
		Value:    value,
		Path:     "/",
		Domain:   s.authConf.TokenCookie.Domain,
		HttpOnly: !s.authConf.DisableHTTPOnly,
		Secure:   s.enabledTLS,
		SameSite: http.SameSiteLaxMode,
	}
	if value == "" {
		cookie.MaxAge = -1
		cookie.Expires = time.Unix(0, 0)
	}
	http.SetCookie(w, &cookie)
}

// authSess reads the session token from r and checks CSRF when necessary.
// If onClose != nil it will be closed once the session is closed.
func (s *Server) auth(
	w http.ResponseWriter, r *http.Request,
) (sess datapages.Session[struct{}], token string, ok bool) {
	c, err := r.Cookie(s.authConf.TokenCookie.Name)
	if err != nil {
		if errors.Is(err, http.ErrNoCookie) {
			return sess, "", true
		}
		return sess, "", false
	}

	rec, token, ok, err := s.sessionManager.ReadSessionFromCookie(c)
	if err != nil {
		// Transient backend failure; keep the cookie, fail the request.
		http.Error(w, "Service Unavailable", http.StatusServiceUnavailable)
		return datapages.Session[struct{}]{}, "", false
	}
	if !ok {
		// Cookie is stale or malformed; clear it and continue as unauthenticated.
		s.setSessionCookie(w, "")
		return datapages.Session[struct{}]{}, "", true
	}
	sess = datapages.MakeSession(
		rec.UserID, token, rec.IssuedAt, rec.ExpiresAt, rec.Data,
	)

	if !sess.ExpiresAt().IsZero() && !time.Now().Before(sess.ExpiresAt()) {
		// Session has expired; clear the cookie and continue as unauthenticated.
		s.setSessionCookie(w, "")
		return datapages.Session[struct{}]{}, "", true
	}

	if !s.checkCSRF(w, r, sess) {
		return sess, token, false
	}

	return sess, token, true
}

func setupHandlers(s *Server) {
	// Pages
	s.mux.HandleFunc(
		"GET /feed/{$}",
		s.handlePageFeedGET)
	s.mux.HandleFunc(
		"GET /feed/_$/{$}",
		s.handlePageFeedGETStream)
	s.mux.HandleFunc(
		"GET /feed/_$/anon/{$}",
		s.handlePageFeedGETStreamAnon)
	s.mux.HandleFunc(
		"GET /",
		s.handlePageIndexGET)
	s.mux.HandleFunc(
		"GET /rooms/{$}",
		s.handlePageRoomsGET)
	s.mux.HandleFunc(
		"GET /rooms/_$/{$}",
		s.handlePageRoomsGETStream)
	s.mux.HandleFunc(
		"GET /rooms/_$/anon/{$}",
		s.handlePageRoomsGETStreamAnon)
	s.mux.HandleFunc(
		"POST /feed/tick/{$}",
		s.handlePageFeedPOSTTick)
	s.mux.HandleFunc(
		"POST /rooms/post/{$}",
		s.handlePageRoomsPOSTPost)
	s.mux.HandleFunc(
		"POST /rooms/notice/{$}",
		s.handlePageRoomsPOSTNotice)
}

func (s *Server) httpErrIntern(
	w http.ResponseWriter, _ *http.Request,
	_ *datastar.ServerSentEventGenerator, msg string, err error,
) {
	s.logErr(msg, err)
	switch {
	case errors.Is(err, datapages.ErrBadRequest):
		http.Error(w, http.StatusText(http.StatusBadRequest), http.StatusBadRequest)
	case errors.Is(err, datapages.ErrForbidden):
		http.Error(w, http.StatusText(http.StatusForbidden), http.StatusForbidden)
	case errors.Is(err, datapages.ErrNotFound):
		http.Error(w, http.StatusText(http.StatusNotFound), http.StatusNotFound)
	case errors.Is(err, datapages.ErrConflict):
		http.Error(w, http.StatusText(http.StatusConflict), http.StatusConflict)
	default:
		http.Error(w, http.StatusText(http.StatusInternalServerError), http.StatusInternalServerError)
	}
}

func (s *Server) handlePageFeedGET(w http.ResponseWriter, r *http.Request) {
	p := app.PageFeed{
		App: s.app,
	}
	body, err := p.GET(r)
	if err != nil {
		s.httpErrIntern(w, r, nil, "handling PageFeed.GET", err)
		return
	}
	genericHead := s.app.Head(r)

	bodyAttrs := func(w http.ResponseWriter) {
		writeBodyAttrOnVisibilityChange(w)
	}

	bodySuffix := func(w http.ResponseWriter) {
	}

	if err := s.writeHTML(
		w, r, datapages.Session[struct{}]{}, genericHead, nil, body, bodyAttrs, bodySuffix,
	); err != nil {
		s.logErr("rendering PageFeed", err)
		return
	}
}

func (s *Server) handlePageFeedGETStream(w http.ResponseWriter, r *http.Request) {
	if !s.checkIsDSReq(w, r) {
		return
	}
	sess, sessToken, ok := s.auth(w, r)
	if !ok {
		return
	}

	if sess.UserID() == "" {
		// The query carries the signals a stream subscribes by,
		// which the anonymous route needs as much as this one.
		target := r.URL.Path + "/anon"
		if r.URL.RawQuery != "" {
			target += "?" + r.URL.RawQuery
		}
		http.Redirect(w, r, target, http.StatusSeeOther)
		return
	}
	if !s.checkUserSubject(w, sess.UserID()) {
		return
	}

	p := app.PageFeed{
		App: s.app,
	}
	s.handleStreamRequest(w, r, sessToken, sess, evSubjPageFeed(sess.UserID()),
		nil,
		nil,
		func(
			streamID datapages.StreamID,
			sse *datastar.ServerSentEventGenerator, ch <-chan msgbroker.Message,
		) {
			var eventTicked app.EventTicked
			var eventNoticed app.EventNoticed
			for msg := range ch {
				switch {
				case msg.Subject == EvSubjTicked:
					eventTicked = app.EventTicked{}
					if err := json.Unmarshal(msg.Data, &eventTicked); err != nil {
						s.logErr("unmarshaling EventTicked JSON", err)
						continue
					}
					if err := p.OnTicked(eventTicked, newSSE(sse)); err != nil {
						s.logErr("handling PageFeed.OnTicked", err)
					}
				case strings.HasPrefix(msg.Subject, EvSubjPrefNoticed):
					eventNoticed = app.EventNoticed{}
					if err := json.Unmarshal(msg.Data, &eventNoticed); err != nil {
						s.logErr("unmarshaling EventNoticed JSON", err)
						continue
					}
					if err := p.OnNoticed(eventNoticed, newSSE(sse)); err != nil {
						s.logErr("handling PageFeed.OnNoticed", err)
					}
				}
			}
		})
}

