func (s *Server) handlePageFeedPOSTTick(
	w http.ResponseWriter, r *http.Request,
) {
	if !s.checkIsDSReq(w, r) {
		return
	}
	// CSRF protection covers every state-changing action, including
	// the ones that read nothing of the session.
	if _, _, ok := s.auth(w, r); !ok {
		return
	}
	r.Body = http.MaxBytesReader(w, r.Body, DefaultBodySizeLimit)
	var signals datapages.Signals[struct {
		N int `json:"n"`
	}]
	if err := datastar.ReadSignals(r, &signals.Values); err != nil {
		s.httpErrBad(w, "reading signals", err)
		return
	}

	dispatchTicked := dispatcherEventTicked{s: s, ctx: r.Context()}
	p := app.PageFeed{
		App: s.app,
	}
	err := p.POSTTick(r, signals, dispatchTicked)
	if err != nil {
		s.httpErrIntern(w, r, nil, "handling action PageFeed.Tick", err)
		return
	}
}

